const input = $('Governance - Open Trace').first().json;
const original = String(input.candidate_material || '');
const counts = {};
let sanitized = original;

const rules = [
  ['EMAIL', /[\w.+-]+@[\w-]+\.[\w.-]+/g],
  ['PHONE', /(?:\+?\d[\d\s().-]{7,}\d)/g],
  ['LINKEDIN_URL', /https?:\/\/(?:www\.)?linkedin\.com\/[^\s]+/gi]
];

for (const [type, pattern] of rules) {
  const matches = sanitized.match(pattern) || [];
  counts[type] = matches.length;
  sanitized = sanitized.replace(pattern, `[${type}_REDACTED]`);
}

if (input.candidate_name && input.candidate_name !== 'Unnamed candidate') {
  sanitized = sanitized.split(String(input.candidate_name)).join('[NAME_REDACTED]');
  counts.NAME = 1;
}

return [{
  json: {
    ...input,
    alias: `Candidate ${String(input.candidate_id || '').slice(-6)}`,
    sanitized_candidate_material: sanitized,
    pii_masked: Object.values(counts).some(value => value > 0),
    pii_redaction_counts: counts,
    candidate_material: undefined,
    email: undefined,
    phone: undefined
  }
}];

const input = $input.first().json;
const text = String(input.sanitized_candidate_material || '');

const patterns = [
  ['ignore_instructions', /(ignore|disregard|forget)\s+(all\s+)?(previous\s+|above\s+)?(instructions?|rules?|prompts?)/i],
  ['role_change', /(you are now|act as if you were|new role)/i],
  ['score_request', /(assign|give|set)\s+.{0,25}(score|100|maximum)/i],
  ['verdict_request', /(recommend|mark|return)\s+.{0,25}(eligible|hire|approved)/i],
  ['prompt_exfiltration', /(system\s*prompt|reveal\s+your\s+instructions|show\s+your\s+prompt)/i]
];

const detected = patterns.filter(([, pattern]) => pattern.test(text)).map(([name]) => name);

return [{
  json: {
    ...input,
    injection_detected: detected.length > 0,
    detected_patterns: detected.join(', ') || 'none'
  }
}];

const config = $('Prompt Injection Guard').first().json;
const rows = $input.all().map(item => item.json).filter(row => row && row.cost_usd != null);
const spendToday = Number(rows.reduce((sum, row) => sum + Number(row.cost_usd || 0), 0).toFixed(6));
const budget = Number(config.daily_budget_usd || 2);
const consumedRatio = budget > 0 ? spendToday / budget : 0;

return [{
  json: {
    ...config,
    spend_today: spendToday,
    executions_today: rows.length,
    budget_percentage: Math.round(consumedRatio * 1000) / 10,
    budget_available: spendToday < budget,
    burn_rate_alert: consumedRatio >= 0.8
  }
}];

function readNode(name) {
  try { return $(name).first().json; } catch (error) { return null; }
}

const governance = readNode('Governance - Open Trace') || {};
const security = readNode('Prompt Injection Guard') || {};
const eligibility = readNode('Worker - Eligibility Screening');
const scorecard = readNode('Worker - Match Scorecard');
const current = $input.first().json;
const rag = readNode('Job Context and Rubric') || current;
const supervisorRaw = readNode('Run AI Evaluation Supervisor');
const supervisor = supervisorRaw?.output || null;

const inputTokens = Number(eligibility?.tokens_in || 0) + Number(scorecard?.tokens_in || 0);
const outputTokens = Number(eligibility?.tokens_out || 0) + Number(scorecard?.tokens_out || 0);
const inputPrice = Number(governance.input_price_per_million ?? 0.30);
const outputPrice = Number(governance.output_price_per_million ?? 2.50);
const costUsd = Number(((inputTokens / 1e6) * inputPrice + (outputTokens / 1e6) * outputPrice).toFixed(6));
const modelCalls = (eligibility ? 1 : 0) + (scorecard ? 1 : 0);
const decisionBand = current.decision_band || 'UNKNOWN';
const noRagCoverage = decisionBand === 'NO_RAG_COVERAGE';
const confidence = noRagCoverage ? null : Number(scorecard?.confidence ?? eligibility?.confidence ?? 0);
const phase = Number(governance.deployment_phase ?? 2);
const threshold = Number(governance.confidence_threshold ?? 0.70);

let autonomyLevel;
if (decisionBand === 'QA_REVIEW') autonomyLevel = 'HUMAN_APPROVAL';
else if (['BLOCKED', 'DEFERRED', 'NO_RAG_COVERAGE'].includes(decisionBand)) autonomyLevel = 'CLOSED';
else if (phase === 0) autonomyLevel = 'SHADOW';
else if (phase >= 3 && confidence >= threshold && ['GREEN', 'NOT_ELIGIBLE'].includes(decisionBand)) autonomyLevel = 'AUTONOMOUS';
else autonomyLevel = 'HUMAN_APPROVAL';

const reasoningSummary = [
  eligibility ? `ELIGIBILITY: ${eligibility.reasoning || ''}` : null,
  scorecard ? `SCORECARD: ${scorecard.reasoning || ''}` : null
].filter(Boolean).join(' || ') || 'No model inference was performed.';

return [{
  json: {
    trace_id: governance.trace_id,
    date: governance.date,
    timestamp: new Date().toISOString(),
    environment: governance.environment,
    deployment_phase: phase,
    autonomy_level: autonomyLevel,
    candidate_id: governance.candidate_id,
    job_id: governance.job_id,
    agent: 'Candidate Screening Orchestrator',
    prompt_version: governance.prompt_version,
    rubric_version: governance.rubric_version,
    eligible: eligibility?.eligible === true,
    match_score: Number(scorecard?.match_score ?? current.match_score ?? 0),
    decision_band: decisionBand,
    confidence,
    agent_thought: reasoningSummary.slice(0, 1800),
    evidence: String(scorecard?.breakdown || eligibility?.must_have_details || 'No evidence recorded').slice(0, 1800),
    tokens_in: inputTokens,
    tokens_out: outputTokens,
    cost_usd: costUsd,
    cost_method: 'character_estimate_divided_by_4',
    cost_scenario: modelCalls === 0 ? 'no_inference' : modelCalls === 1 ? 'single_model_call' : 'standard_loop',
    latency_ms: Date.now() - Number(governance.started_at_ms || Date.now()),
    pii_masked: security.pii_masked ?? false,
    injection_detected: security.injection_detected === true,
    decision_route: decisionBand,
    action: current.action || 'No action recorded',
    decided_by: 'agent',
    supervisor_executed: supervisor !== null,
    supervisor_approved: supervisor?.approved ?? null,
    supervisor_factual_accuracy: supervisor ? Number(supervisor.factual_accuracy ?? 0) : null,
    supervisor_evidence_sufficiency: supervisor ? Number(supervisor.evidence_sufficiency ?? 0) : null,
    supervisor_rubric_consistency: supervisor ? Number(supervisor.rubric_consistency ?? 0) : null,
    supervisor_hallucination_detected: supervisor?.hallucination_detected ?? null,
    supervisor_critique: supervisor ? String(supervisor.critique || '').slice(0, 1800) : '',
    rag_executed: rag?.rag_executed ?? false,
    rag_coverage: rag?.rag_coverage ?? false,
    rag_document_id: rag?.rag_metadata?.document_id ?? '',
    rag_document_title: rag?.rag_metadata?.document_title ?? '',
    rag_version: rag?.rag_metadata?.version ?? '',
    rag_source_file: rag?.rag_metadata?.source_file ?? '',
    rag_query: rag?.rag_query ?? '',
    node_name: 'Instrumentation and Audit Record',
    tool_output: JSON.stringify({ decision_band: decisionBand, eligible: eligibility?.eligible === true, match_score: Number(scorecard?.match_score ?? current.match_score ?? 0), confidence, action: current.action || 'No action recorded' }).slice(0, 1800),
    system_prompt_snapshot: `prompt_version=${governance.prompt_version || 'unversioned'} | rubric_version=${governance.rubric_version || 'unversioned'}`
  }
}];

