return [{
  json: {
    trace_id: governance.trace_id,
    idempotency_key: governance.idempotency_key,
    sanitized_candidate_material: security.sanitized_candidate_material || '',
    eligibility_result: eligibility,
    scorecard_result: scorecard,
    rubric: job.rubric || job.scorecard || JSON.stringify(job),
    rag_metadata: job.rag_metadata || {},
    audited_at: new Date().toISOString()
  }
}];

const score = $('Worker - Match Scorecard').first().json;
const judge = $('Run AI Evaluation Supervisor').first().json.output;

return [{
  json: {
    ...score,

    supervisor_approved: judge.approved === true,
    supervisor_factual_accuracy: Number(judge.factual_accuracy),
    supervisor_evidence_sufficiency: Number(judge.evidence_sufficiency),
    supervisor_rubric_consistency: Number(judge.rubric_consistency),
    supervisor_hallucination_detected: judge.hallucination_detected === true,
    supervisor_critique: judge.critique
  }
}];

