  try { return $(name).first().json; } catch (error) { return {}; }
}

const governance = readNode('Governance - Open Trace');
const security = readNode('Data Minimization - Mask PII');
const eligibility = readNode('Worker - Eligibility Screening');
const job = readNode('Job Context and Rubric');

return [{
  json: {
    trace_id: governance.trace_id,
    idempotency_key: governance.idempotency_key,
    evaluation_type: 'ELIGIBILITY_NOT_ELIGIBLE',
    sanitized_candidate_material: security.sanitized_candidate_material || '',
    eligibility_result: eligibility,
    scorecard_result: {},
    rubric: job.rubric || job.scorecard || JSON.stringify(job),
    rag_metadata: job.rag_metadata || {},
    audited_at: new Date().toISOString()
  }
}];

const eligibility = $('Worker - Eligibility Screening').first().json;
const supervisor = $('Run AI Evaluation Supervisor').first().json.output;

return [{
  json: {
    ...eligibility,
    decision_band: 'NOT_ELIGIBLE',
    match_score: 0,
    action: 'The candidate did not demonstrate one or more must-have requirements.',
    supervisor_approved: supervisor.approved === true,
    supervisor_factual_accuracy: Number(supervisor.factual_accuracy),
    supervisor_evidence_sufficiency: Number(supervisor.evidence_sufficiency),
    supervisor_rubric_consistency: Number(supervisor.rubric_consistency),
    supervisor_hallucination_detected: supervisor.hallucination_detected === true,
    supervisor_critique: supervisor.critique
  }
}];
